  function header(){return `<a class="skip-link" href="#main-content">Skip to content</a><div class="preview-bar">Store preview <span>·</span> Demo prices in AUD <span>·</span> No live payments <a href="#" class="preview-learn" data-modal="preview">About this preview</a></div><header class="site-header"><div class="container header-inner"><a class="wordmark" href="#/" aria-label="Prevora home">prevora<span class="wordmark-dot">.</span></a><nav class="header-nav" aria-label="Main navigation"><a href="#/shop" class="nav-shop" data-shop-menu aria-expanded="false">Shop${icon('chevron',13)}</a><a href="#/brand/lndu">The LNDU range</a><a href="#/about">Our story</a><a href="#/business">For business</a><a href="#/support">Support</a></nav><div class="header-tools"><button class="icon-button" aria-label="Search products" data-open-search>${icon('search',21)}</button><a class="icon-button" href="#/cart" aria-label="Demo shopping bag, ${cartCount()} items">${icon('bag',21)}<span class="cart-count" ${cartCount() ? '' : 'hidden'}>${cartCount()}</span></a><button class="icon-button menu-toggle" aria-label="Open menu" aria-expanded="false" data-mobile-menu>${icon('menu',22)}</button></div></div><div class="shop-menu" id="shop-menu"><div class="container shop-menu-grid"><div><p class="menu-label">Explore</p><div class="shop-menu-links"><a href="#/shop">Shop the full range ${icon('arrow',14)}</a><a href="#/brand/lndu">Meet LNDU</a><a href="#/business">Products for your project</a></div></div><div><p class="menu-label">Shop by category</p><div class="shop-menu-links">${CATEGORIES.map(c => `<a href="#/shop/${c.id}">${c.name}</a>`).join('')}</div></div><a class="shop-menu-brand" href="#/brand/lndu"><img src="${asset('lndu-h10-product.png')}" alt="LNDU H10 smart lock"><div><p class="menu-label">Featured brand</p><h3>LNDU</h3><p>Technology that fits the everyday.</p></div></a></div></div><nav class="mobile-nav" aria-label="Mobile navigation"><a href="#/shop">Shop the full range ${icon('arrow',17)}</a><div class="mobile-range-links">${CATEGORIES.map(c => `<a href="#/shop/${c.id}">${c.name}</a>`).join('')}</div><a href="#/brand/lndu">The LNDU range</a><a href="#/about">Our story</a><a href="#/business">For business</a><a href="#/support">Support</a></nav></header>`;}
